using System.Linq;using UnityEngine;using ProjectWait.M.Elevator;using Object=UnityEngine.Object;public static class InspectFeedbackMO{public static string Main(){return Newtonsoft.Json.JsonConvert.SerializeObject(Object.FindObjectsByType<ElevatorButtonFeedback>(FindObjectsInactive.Include,FindObjectsSortMode.None).Select(f=>new{name=f.name,active=f.gameObject.activeInHierarchy,observation=f.GetComponent<ElevatorObservation>()?.clue.ToString(),description=f.GetComponent<ElevatorObservation>()?.hasDescription,mask=f.outlineTarget?f.outlineTarget.name:null,ownerTarget=f.GetComponent<ElevatorObservation>()?.outlineTarget?.name,ownerFeedback=f.GetComponent<ElevatorObservation>()?.feedback?.name}));}}